			    var checkedRow = app.lookup("grd1").getCheckRowIndices();
			    var dsList = app.lookup("dsList");
			    var dmRenu = app.lookup("dmRenu");
			    
			    dsList.setValue(0, "CRTF_ISSU_MNG_NO", app.lookup("dmRenu").getValue("CRTF_ISSU_MNG_NO"));
